#### Unit Tests Delta-Hedging ####import pytestimport numpy as npfrom quant_finance.options.delta_hedging import delta_hedge#1. Return correct general outputs and characteristicsdef test_delta_hedging_general_outputs():    N = 252    results = delta_hedge(        S_0=100,        K=100,        r=0.05,        T=1.0,        sigma=0.20,        N=N,        q=0.0,        seed=0,        option_type="call",        position="short",    )    # Check returned keys    expected_keys = {        "S_path",        "option_prices",        "delta_path",        "stock_positions",        "cash_account",        "payoff",        "terminal_pnl",    }    assert set(results.keys()) == expected_keys    # Check array lengths and finite path values    expected_lengths = {        "S_path": N + 1,        "option_prices": N,        "delta_path": N,        "stock_positions": N,        "cash_account": N,    }    for name, expected_length in expected_lengths.items():        assert len(results[name]) == expected_length        assert np.all(np.isfinite(results[name]))    # Check finite scalar outputs    assert np.isfinite(results["payoff"])    assert np.isfinite(results["terminal_pnl"])            #2. Reproducibility with constant seeddef test_delta_hedging_same_seed():        terminal_pnl1 = delta_hedge(        S_0=100,        K=100,        r=0.05,        T=1.0,        sigma=0.20,        N=252,        q=0.0,        seed=0,        option_type="call",        position="short",    )["terminal_pnl"]        terminal_pnl2 = delta_hedge(        S_0=100,        K=100,        r=0.05,        T=1.0,        sigma=0.20,        N=252,        q=0.0,        seed=0,        option_type="call",        position="short",    )["terminal_pnl"]        assert terminal_pnl1 == terminal_pnl2        #3. Long vs Short positions produce opposite P&L    def test_delta_hedging_long_short_opposite_pnl():    long_pnl = delta_hedge(        S_0=100,        K=100,        r=0.05,        T=1.0,        sigma=0.20,        N=252,        q=0.0,        seed=0,        option_type="call",        position="long",    )["terminal_pnl"]    short_pnl = delta_hedge(        S_0=100,        K=100,        r=0.05,        T=1.0,        sigma=0.20,        N=252,        q=0.0,        seed=0,        option_type="call",        position="short",    )["terminal_pnl"]    assert long_pnl == pytest.approx(-short_pnl)                                                                    